func:
// 5분마다 제어이력 미동기화 백로그를 서버에 보고. 보고가 끊기거나 나이가 커지면 서버가 알림.
var row = (msg.payload && msg.payload[0]) || { cnt: 0, oldest_sec: 0 };
var serverUrl = env.get('SERVER_URL') || global.get('pcServerUrl') || 'https://api.smartgreen.kr';
var farmId = env.get('FARM_ID') || global.get('farmId') || 'farm_0001';
return {
    method: 'POST',
    url: serverUrl + '/internal/control-sync-status',
    headers: { 'Content-Type': 'application/json', 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' },
    payload: { farmId: farmId, unsyncedCount: row.cnt || 0, oldestUnsyncedSec: row.oldest_sec || 0 },
    requestTimeout: 8000
};
